package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TokenBuffer_writeNumber_TriageGen1Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // TokenBuffer requires an ObjectCodec to be initialized via constructor
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteNumber_PositiveFloat() throws IOException {
        float value = 123.45f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(123.45f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumber_NegativeFloat() throws IOException {
        float value = -0.001f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(-0.001f, parser.getFloatValue(), 0.0001f);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        float value = 0.0f;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(0.0f, parser.getFloatValue(), 0.0f);
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        float value = Float.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertTrue(Float.isInfinite(parser.getFloatValue()));
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        float value = Float.NaN;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertTrue(Float.isNaN(parser.getFloatValue()));
    }

    @Test
    public void testWriteNumber_LargeFloat() throws IOException {
        float value = Float.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(Float.MAX_VALUE, parser.getFloatValue(), 0.0f);
    }

    @Test
    public void testWriteNumber_SmallFloat() throws IOException {
        float value = Float.MIN_VALUE;
        tokenBuffer.writeNumber(value);

        JsonParser parser = tokenBuffer.asParser(mapper);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(Float.MIN_VALUE, parser.getFloatValue(), 0.0f);
    }

    @Test
    public void testWriteNumber_MultipleValues() throws IOException {
        tokenBuffer.writeNumber(1.0f);
        tokenBuffer.writeNumber(2.5f);

        JsonParser parser = tokenBuffer.asParser(mapper);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(1.0f, parser.getFloatValue(), 0.0f);

        Assert.assertTrue(parser.nextToken());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.currentToken());
        Assert.assertEquals(2.5f, parser.getFloatValue(), 0.0f);
    }
}
